return [{json:{
  _isTest: true,
  workflow: {name:'AI News Podcast',id:'TEST'},
  execution: {
    id:'TEST-001',
    url:'',
    lastNodeExecuted:'DeepSeek — Análisis',
    error: {message:'PRUEBA: Respuesta vacía del proveedor de IA'}
  }
}}];

// Formato seguro para Telegram HTML. No expone stacks ni cuerpos completos de APIs.
const data = $input.first()?.json ?? {};
const execution = data.execution ?? {};
const workflow = data.workflow ?? {};
const error = execution.error ?? data.error ?? {};
const isTest = data._isTest === true;
const redact = (value) => String(value ?? 'No disponible')
  .replace(/Bearer\s+[A-Za-z0-9._~+/-]+/gi, 'Bearer [OCULTO]')
  .replace(/sk-[A-Za-z0-9_-]{12,}/g, '[API_KEY_OCULTA]');
const esc = (value) => redact(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;');
const wf = esc(workflow.name || 'Podcast diario');
const node = esc(execution.lastNodeExecuted || error.node?.name || 'No identificado');
const msg = esc(String(error.message || error.description || 'Error sin mensaje').slice(0, 900));
const id = esc(execution.id || 'No disponible');
const date = new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid', hour12: false });
const url = String(execution.url || '');
const validUrl = /^https?:\/\//i.test(url);
const lines = [
  isTest ? '🧪 <b>PRUEBA DE ALERTA — n8n</b>' : '🚨 <b>FALLO — PODCAST DIARIO</b>',
  `<b>Workflow:</b> ${wf}`,
  `<b>Nodo:</b> ${node}`,
  `<b>Error:</b> ${msg}`,
  `<b>Execution ID:</b> ${id}`,
  `<b>Detectado:</b> ${esc(date)} (Madrid)`,
];
if (validUrl) lines.push(`<a href="${esc(url)}">Abrir ejecución fallida</a>`);
if (isTest) lines.push('Este mensaje es una simulación. No indica un fallo real.');
return [{json:{text:lines.join('\n'),isTest,workflow:workflow.name || ''}}];
